SELECT * 
FROM customer_shopping_behavior_clean;

SELECT DISTINCT customer_id
FROM customer_shopping_behavior_clean;

-- Q1. What is the total revenue generated by male vs. female customers

SELECT gender , SUM(purchase_amount) AS revenue
FROM customer_shopping_behavior_clean
GROUP BY gender
ORDER BY 2;

--  Q2. Which customers used a discount but still spent more than the average purchase amount? 

SELECT ROUND(AVG(purchase_amount) , 0) average
FROM customer_shopping_behavior_clean; 

SELECT customer_id , gender , discount_applied, purchase_amount
FROM customer_shopping_behavior_clean
WHERE discount_applied = 'Yes'AND purchase_amount > (
SELECT AVG(purchase_amount)
FROM customer_shopping_behavior_clean
);

-- Q3. Which 5 states (location) have the highest average purchase amount, but only among states with at least 70 purchases?

SELECT COUNT(customer_id) AS total_purchases , location 
FROM customer_shopping_behavior_clean
GROUP BY location;
 
 
SELECT COUNT(customer_id) total_purchases ,AVG(purchase_amount) avg_amount,location
FROM customer_shopping_behavior_clean
GROUP BY location 
HAVING COUNT(customer_id)>=70
ORDER BY 2 DESC
LIMIT 5;


-- Q4. Compare the average Purchase Amounts between Standard and Express Shipping.

SELECT shipping_type , AVG(purchase_amount) AS avg_amount
FROM customer_shopping_behavior_clean
GROUP BY shipping_type
ORDER BY 2 DESC;

-- Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

SELECT COUNT(customer_id) AS Total_Customers , 
subscription_status, AVG(purchase_amount) AS Average_spend ,
SUM(purchase_amount) AS Total_spend
FROM customer_shopping_behavior_clean
GROUP BY subscription_status ;

-- Q6. Which 5 products have the highest percentage of purchases with discounts applied?

SELECT * 
FROM customer_shopping_behavior_clean;

SELECT item_purchased,
ROUND(100.0 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) AS discount_rate
FROM customer_shopping_behavior_clean
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

-- Q7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment.

SELECT * 
FROM customer_shopping_behavior_clean;

SELECT MIN(previous_purchases) AS min,MAX(previous_purchases) AS max
FROM customer_shopping_behavior_clean;

WITH Customer_type AS (
SELECT customer_id ,  previous_purchases ,
CASE WHEN previous_purchases BETWEEN 1 AND 10 THEN 'NEW'
     WHEN previous_purchases BETWEEN 10 AND 20 THEN 'RETURNING'
     ELSE 'LOYAL'
     END AS Customer_segment
FROM customer_shopping_behavior_clean
)
SELECT COUNT(*) AS Total_customers , Customer_segment
FROM Customer_type
GROUP BY Customer_segment;

-- Q8. What are the top 3 most purchased products within each category? 

SELECT * 
FROM customer_shopping_behavior_clean;

SELECT item_purchased,COUNT(customer_id) AS total_purchase, category,
DENSE_RANK() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC ) AS product_rank
FROM customer_shopping_behavior_clean
GROUP BY category,item_purchased;

WITH Product_rank AS
(
SELECT item_purchased,COUNT(customer_id) AS total_purchase , category,
DENSE_RANK() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC ) AS product_rank
FROM customer_shopping_behavior_clean
GROUP BY category,item_purchased 
)
SELECT *
FROM Product_rank
WHERE product_rank <=3;

-- Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

SELECT COUNT(*) AS repeat_buyers , subscription_status
FROM customer_shopping_behavior_clean
WHERE previous_purchases > 5
GROUP BY subscription_status;

-- Q10. What is the revenue contribution of each age group? 

SELECT SUM(purchase_amount) AS total_revenue
FROM customer_shopping_behavior_clean;

SELECT SUM(purchase_amount) AS total_revenue , age_group
FROM customer_shopping_behavior_clean
GROUP BY age_group
ORDER BY 1 DESC;
